{
  "name": "sharp-compact",
  "version": "0.3.0",
  "description": "Every compaction keeps what matters: the session writes its own handoff brief first.",
  "author": {
    "name": "Rémy Lespagnol"
  },
  "license": "MIT",
  "userConfig": {
    "timeoutSeconds": {
      "type": "number",
      "title": "Brief timeout (seconds)",
      "description": "How long to wait for the session's brief before compacting normally.",
      "default": 90,
      "min": 10,
      "max": 600
    },
    "briefPrompt": {
      "type": "string",
      "title": "Brief prompt",
      "description": "Replaces the default prompt that asks the session for its handoff brief. Empty uses the default.",
      "default": ""
    },
    "idleMinutes": {
      "type": "number",
      "title": "Idle reminder (minutes)",
      "description": "After this many idle minutes, warn that the prompt cache is about to expire (1h on subscriptions, use 4 for the 5-minute API cache). 0 turns it off.",
      "default": 55,
      "min": 0,
      "max": 600
    },
    "idleCompact": {
      "type": "boolean",
      "title": "Compact when idle",
      "description": "Compact automatically instead of only warning when the idle time is reached.",
      "default": false
    }
  }
}
